DROP TABLE IF EXISTS `audit_trail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_trail` (
  `audit_id` int NOT NULL AUTO_INCREMENT,
  `shop_id` varchar(255) DEFAULT NULL,
  `invoice_id` varchar(255) DEFAULT NULL,
  `event_type` enum('Invoice Generated','Payment Made','Partially Paid','Arrears Updated','Fine Applied','Arrest Action','VAT Updated','Operation Fee Updated','Manual Edit','Correction') NOT NULL,
  `event_description` text NOT NULL,
  `old_value` text,
  `new_value` text,
  `edit_reason` text,
  `event_date` datetime DEFAULT NULL,
  `user_actioned` varchar(255) NOT NULL,
  PRIMARY KEY (`audit_id`),
  KEY `shop_id` (`shop_id`),
