--
-- Table structure for table `invoices`
--

DROP TABLE IF EXISTS `invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoices` (
  `invoice_id` varchar(255) NOT NULL,
  `shop_id` varchar(10) NOT NULL,
  `month_year` datetime NOT NULL,
  `rent_amount` decimal(10,2) NOT NULL,
  `operation_fee` decimal(10,2) DEFAULT '0.00',
  `vat_amount` decimal(10,2) DEFAULT '0.00',
  `previous_balance` decimal(10,2) DEFAULT '0.00',
  `fines` decimal(10,2) DEFAULT '0.00',
  `previous_fines` decimal(10,2) DEFAULT '0.00',
  `total_arrears` decimal(10,2) DEFAULT '0.00',
  `total_amount` decimal(10,2) NOT NULL,
  `status` enum('Paid','Unpaid','Arrest','Partially Paid') DEFAULT 'Unpaid',
  `printedtime` int DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`invoice_id`),
  KEY `shop_id` (`shop_id`),
  CONSTRAINT `invoices_ibfk_1` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`shop_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

