DROP TABLE IF EXISTS `operation_fees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `operation_fees` (
  `operation_fee_id` int NOT NULL AUTO_INCREMENT,
  `shop_id` varchar(10) NOT NULL,
  `invoice_id` varchar(255) NOT NULL,
  `operation_amount` decimal(10,2) NOT NULL,
  `paid_amount` decimal(10,2) DEFAULT '0.00',
  `generate_date` datetime NOT NULL,
  `paid_date` datetime DEFAULT NULL,
  `status` enum('Unpaid','Paid','Partially Paid','Arrest') DEFAULT 'Unpaid',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`operation_fee_id`),
  KEY `shop_id` (`shop_id`),
  KEY `invoice_id` (`invoice_id`),
  CONSTRAINT `operation_fees_ibfk_105` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`shop_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `operation_fees_ibfk_106` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`invoice_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
